const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define region (northern Madagascar between latitude -12 to -15)
  const region = ee.Geometry.Rectangle([43, -15, 50, -12]); // Madagascar longitude approx 43-50E

  // 2. Get CHIRPS precipitation data
  const chirps = ee.ImageCollection("UCSB-CHG/CHIRPS/DAILY");

  // Target period: Dec 2018 + Jan 2019
  const targetPeriod = chirps
    .filterDate('2018-12-01', '2019-01-31')
    .filterBounds(region);

  // Historical baseline: Dec-Jan periods from 2000-2019
  const historicalPeriods = ee.ImageCollection(ee.List.sequence(2000, 2019).map(function(year) {
    const start = ee.Date.fromYMD(year, 11, 1); // December (month 11 in 0-based)
    const end = ee.Date.fromYMD(ee.Number(year).add(1), 1, 31); // January next year
    return chirps
      .filterDate(start, end)
      .filterBounds(region)
      .sum()
      .set('year', year);
  }).flatten());

  // Check if collections are empty
  const targetCount = targetPeriod.size().getInfo();
  const historicalCount = historicalPeriods.size().getInfo();

  console.log(`Target period images: ${targetCount}`);
  console.log(`Historical periods: ${historicalCount}`);

  if (targetCount === 0 || historicalCount === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate total precipitation for target period
  const targetPrecip = targetPeriod.sum();

  // Calculate historical average
  const historicalAvg = historicalPeriods.mean();

  // Get pixel counts to check for valid data
  const targetCountPixels = targetPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const historicalCountPixels = historicalAvg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Target valid pixels: ${targetCountPixels}`);
  console.log(`Historical valid pixels: ${historicalCountPixels}`);

  if (targetCountPixels === 0 || historicalCountPixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate mean precipitation values
  const targetMean = targetPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const historicalMean = historicalAvg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Target period mean: ${targetMean?.toFixed(2)} mm`);
  console.log(`Historical mean: ${historicalMean?.toFixed(2)} mm`);

  // Validate calculations
  if (targetMean === null || historicalMean === null || 
      isNaN(targetMean) || isNaN(historicalMean) ||
      targetMean < 0 || historicalMean < 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare and determine answer
  if (targetMean < historicalMean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
